// Reads the outlines of the music symbols SimpleMusic Pro draws out of Bravura.otf and writes them as path data
// into a C# source file, so that the program needs neither the font file nor a font reader at run time.
//
//   GlyphExtractor <Bravura.otf> <output.cs> [--list]
//
// Bravura (SIL Open Font Licence 1.1, Copyright (c) 2015 Steinberg Media Technologies GmbH) is not kept in
// this repository; download it from https://github.com/steinbergmedia/bravura (redist/otf/Bravura.otf).
// Only these outlines, as numbers, are in the generated file; see THIRD-PARTY-NOTICES.txt.

using System.Buffers.Binary;
using System.Globalization;
using System.Text;

if (args.Length < 2)
{
    Console.Error.WriteLine("Usage: GlyphExtractor <Bravura.otf> <output.cs> [--list]");
    return 1;
}

byte[] font = File.ReadAllBytes(args[0]);
var tables = new Dictionary<string, (int Offset, int Length)>();
int tableCount = BinaryPrimitives.ReadUInt16BigEndian(font.AsSpan(4));
for (int i = 0; i < tableCount; i++)
{
    int at = 12 + i * 16;
    string tag = Encoding.ASCII.GetString(font, at, 4);
    tables[tag] = (BinaryPrimitives.ReadInt32BigEndian(font.AsSpan(at + 8)), BinaryPrimitives.ReadInt32BigEndian(font.AsSpan(at + 12)));
}
if (!tables.TryGetValue("CFF ", out var cffTable))
{
    Console.Error.WriteLine("This font has no CFF outlines (is it Bravura.otf?).");
    return 1;
}
var cff = new Cff(font, cffTable.Offset);
Console.WriteLine($"{cff.GlyphCount} glyphs in the font");
if (args.Contains("--list"))
{
    foreach (var name in cff.Names.Keys.OrderBy(n => n, StringComparer.Ordinal)) Console.WriteLine(name);
    return 0;
}

// The symbols the program uses: their SMuFL names (https://w3c.github.io/smufl/latest/) and code points. Bravura
// names its glyphs by code point (uniE050), so the code point is what finds one.
(string Name, int Code)[] wanted =
[
    ("brace", 0xE000), ("bracket", 0xE002),
    ("repeatDots", 0xE043), ("segno", 0xE047), ("coda", 0xE048),
    ("gClef", 0xE050), ("gClef8vb", 0xE052), ("cClef", 0xE05C), ("fClef", 0xE062), ("6stringTabClef", 0xE06D),
    ("timeSig0", 0xE080), ("timeSig1", 0xE081), ("timeSig2", 0xE082), ("timeSig3", 0xE083), ("timeSig4", 0xE084),
    ("timeSig5", 0xE085), ("timeSig6", 0xE086), ("timeSig7", 0xE087), ("timeSig8", 0xE088), ("timeSig9", 0xE089),
    ("timeSigCommon", 0xE08A), ("timeSigCutCommon", 0xE08B),
    ("noteheadDoubleWhole", 0xE0A0), ("noteheadWhole", 0xE0A2), ("noteheadHalf", 0xE0A3), ("noteheadBlack", 0xE0A4), ("noteheadXBlack", 0xE0A9),
    ("noteHalfUp", 0xE1D3), ("noteQuarterUp", 0xE1D5), ("note8thUp", 0xE1D7), ("augmentationDot", 0xE1E7),
    ("flag8thUp", 0xE240), ("flag8thDown", 0xE241), ("flag16thUp", 0xE242), ("flag16thDown", 0xE243),
    ("flag32ndUp", 0xE244), ("flag32ndDown", 0xE245), ("flag64thUp", 0xE246), ("flag64thDown", 0xE247),
    ("accidentalFlat", 0xE260), ("accidentalNatural", 0xE261), ("accidentalSharp", 0xE262), ("accidentalDoubleSharp", 0xE263), ("accidentalDoubleFlat", 0xE264),
    ("articAccentAbove", 0xE4A0), ("articAccentBelow", 0xE4A1), ("articStaccatoAbove", 0xE4A2), ("articStaccatoBelow", 0xE4A3),
    ("articTenutoAbove", 0xE4A4), ("articTenutoBelow", 0xE4A5), ("fermataAbove", 0xE4C0), ("fermataBelow", 0xE4C1),
    ("restDoubleWhole", 0xE4E2), ("restWhole", 0xE4E3), ("restHalf", 0xE4E4), ("restQuarter", 0xE4E5),
    ("rest8th", 0xE4E6), ("rest16th", 0xE4E7), ("rest32nd", 0xE4E8), ("rest64th", 0xE4E9),
    ("dynamicPiano", 0xE520), ("dynamicMezzo", 0xE521), ("dynamicForte", 0xE522), ("dynamicRinforzando", 0xE523), ("dynamicSforzando", 0xE524),
    ("dynamicPPP", 0xE52A), ("dynamicPP", 0xE52B), ("dynamicMP", 0xE52C), ("dynamicMF", 0xE52D), ("dynamicFF", 0xE52F), ("dynamicFFF", 0xE530),
    ("tuplet0", 0xE880), ("tuplet1", 0xE881), ("tuplet2", 0xE882), ("tuplet3", 0xE883), ("tuplet4", 0xE884),
    ("tuplet5", 0xE885), ("tuplet6", 0xE886), ("tuplet7", 0xE887), ("tuplet8", 0xE888), ("tuplet9", 0xE889),
];
var cs = new StringBuilder();
cs.AppendLine("// <auto-generated>");
cs.AppendLine("// Made by tools/GlyphExtractor from Bravura.otf. Do not edit by hand: run the tool again.");
cs.AppendLine("// Bravura is Copyright (c) 2015 Steinberg Media Technologies GmbH, with Reserved Font Name \"Bravura\",");
cs.AppendLine("// and is offered under the SIL Open Font Licence, Version 1.1 (see THIRD-PARTY-NOTICES.txt). The numbers");
cs.AppendLine("// below are the outlines of some of its symbols, in the font's own units (1000 to the em, so a staff");
cs.AppendLine("// space is 250), y upwards, with the origin where SMuFL puts it.");
cs.AppendLine("// </auto-generated>");
cs.AppendLine("namespace SimpleMusicPro.Glyphs;");
cs.AppendLine();
cs.AppendLine("internal static class BravuraData");
cs.AppendLine("{");
cs.AppendLine("    public const int UnitsPerEm = 1000;");
cs.AppendLine();
cs.AppendLine("    /// <summary>Name (as SMuFL calls it), advance width, and the outline as M, L, C and Z steps.</summary>");
cs.AppendLine("    public static readonly (string Name, int Advance, string Path)[] All =");
cs.AppendLine("    [");
int found = 0;
var missing = new List<string>();
foreach (var (name, code) in wanted)
{
    if (!cff.Names.TryGetValue($"uni{code:X4}", out int glyph)) { missing.Add(name); continue; }
    var (width, path) = cff.Outline(glyph);
    cs.AppendLine($"        (\"{name}\", {width.ToString("0", CultureInfo.InvariantCulture)}, \"{path}\"),");
    found++;
}
cs.AppendLine("    ];");
cs.AppendLine("}");
File.WriteAllText(args[1], cs.ToString().Replace("\r\n", "\n").Replace("\n", "\r\n"), new UTF8Encoding(false));
Console.WriteLine($"{found} symbols written to {args[1]}");
if (missing.Count > 0) Console.WriteLine("not found in the font: " + string.Join(", ", missing));
return missing.Count > 0 ? 2 : 0;

/// <summary>Just enough of a Compact Font Format reader to get the glyph outlines of a name-keyed font.</summary>
sealed class Cff
{
    private readonly byte[] _d;
    private readonly int _base;
    private readonly List<(int Start, int End)> _charStrings;
    private readonly List<(int Start, int End)> _globalSubrs;
    private readonly List<(int Start, int End)> _localSubrs;
    private readonly double _defaultWidth, _nominalWidth;

    public int GlyphCount => _charStrings.Count;
    public Dictionary<string, int> Names { get; } = new();

    public Cff(byte[] data, int offset)
    {
        _d = data;
        _base = offset;
        int hdrSize = data[offset + 2];
        int at = offset + hdrSize;
        at = ReadIndex(at, out _);                          // font names
        at = ReadIndex(at, out var topDicts);
        at = ReadIndex(at, out var strings);
        at = ReadIndex(at, out _globalSubrs);
        var top = ReadDict(topDicts[0].Start, topDicts[0].End);
        ReadIndex(_base + (int)top[17][0], out _charStrings); // CharStrings
        // The Private dictionary gives the subroutines local to this font and the widths.
        var priv = top[18];
        int privSize = (int)priv[0], privOffset = _base + (int)priv[1];
        var p = ReadDict(privOffset, privOffset + privSize);
        _defaultWidth = p.TryGetValue(20, out var dw) ? dw[0] : 0;
        _nominalWidth = p.TryGetValue(21, out var nw) ? nw[0] : 0;
        _localSubrs = [];
        if (p.TryGetValue(19, out var subrs)) ReadIndex(privOffset + (int)subrs[0], out _localSubrs);

        // Glyph names: the charset gives each glyph a string id.
        int charset = (int)top[15][0] + _base;
        var sids = new List<int> { 0 };
        int format = data[charset];
        int q = charset + 1;
        if (format == 0) { while (sids.Count < GlyphCount) { sids.Add(Be16(q)); q += 2; } }
        else
        {
            while (sids.Count < GlyphCount)
            {
                int first = Be16(q); q += 2;
                int left = format == 1 ? data[q++] : Be16(q);
                if (format == 2) q += 2;
                for (int k = 0; k <= left && sids.Count < GlyphCount; k++) sids.Add(first + k);
            }
        }
        for (int g = 1; g < sids.Count; g++)
        {
            int sid = sids[g];
            if (sid >= 391) Names[Encoding.ASCII.GetString(data, strings[sid - 391].Start, strings[sid - 391].End - strings[sid - 391].Start)] = g;
        }
    }

    private int Be16(int at) => (_d[at] << 8) | _d[at + 1];

    private int ReadIndex(int at, out List<(int Start, int End)> items)
    {
        items = [];
        int count = Be16(at);
        if (count == 0) return at + 2;
        int offSize = _d[at + 2];
        int Off(int i) { int v = 0; for (int b = 0; b < offSize; b++) v = (v << 8) | _d[at + 3 + i * offSize + b]; return v; }
        int dataStart = at + 3 + (count + 1) * offSize - 1;
        for (int i = 0; i < count; i++) items.Add((dataStart + Off(i), dataStart + Off(i + 1)));
        return dataStart + Off(count);
    }

    private Dictionary<int, double[]> ReadDict(int start, int end)
    {
        var dict = new Dictionary<int, double[]>();
        var operands = new List<double>();
        int i = start;
        while (i < end)
        {
            int b = _d[i++];
            if (b <= 21)
            {
                int op = b == 12 ? 1200 + _d[i++] : b;
                dict[op] = [.. operands];
                operands.Clear();
            }
            else if (b == 28) { operands.Add((short)Be16(i)); i += 2; }
            else if (b == 29) { operands.Add((_d[i] << 24) | (_d[i + 1] << 16) | (_d[i + 2] << 8) | _d[i + 3]); i += 4; }
            else if (b == 30)
            {
                var sb = new StringBuilder();
                bool done = false;
                while (!done)
                {
                    int by = _d[i++];
                    foreach (int nib in new[] { by >> 4, by & 15 })
                    {
                        if (nib <= 9) sb.Append(nib);
                        else if (nib == 10) sb.Append('.');
                        else if (nib == 11) sb.Append('E');
                        else if (nib == 12) sb.Append("E-");
                        else if (nib == 14) sb.Append('-');
                        else if (nib == 15) { done = true; break; }
                    }
                }
                operands.Add(double.Parse(sb.ToString(), CultureInfo.InvariantCulture));
            }
            else if (b >= 32 && b <= 246) operands.Add(b - 139);
            else if (b >= 247 && b <= 250) operands.Add((b - 247) * 256 + _d[i++] + 108);
            else if (b >= 251 && b <= 254) operands.Add(-(b - 251) * 256 - _d[i++] - 108);
        }
        return dict;
    }

    /// <summary>The advance width and the outline of a glyph, as "M x y L x y C x1 y1 x2 y2 x y Z" steps.</summary>
    public (double Width, string Path) Outline(int glyph)
    {
        var sb = new StringBuilder();
        double x = 0, y = 0, width = _defaultWidth;
        bool open = false, widthTaken = false;
        var stack = new List<double>();
        int stems = 0;
        string N(double v) => Math.Round(v, 1).ToString("0.#", CultureInfo.InvariantCulture);

        void Close() { if (open) { sb.Append("Z "); open = false; } }
        void MoveTo(double dx, double dy) { Close(); x += dx; y += dy; sb.Append($"M {N(x)} {N(y)} "); open = true; }
        void LineTo(double dx, double dy) { x += dx; y += dy; sb.Append($"L {N(x)} {N(y)} "); }
        void CurveTo(double dx1, double dy1, double dx2, double dy2, double dx3, double dy3)
        {
            double x1 = x + dx1, y1 = y + dy1, x2 = x1 + dx2, y2 = y1 + dy2;
            x = x2 + dx3; y = y2 + dy3;
            sb.Append($"C {N(x1)} {N(y1)} {N(x2)} {N(y2)} {N(x)} {N(y)} ");
        }
        // The first operator that clears the stack may carry the width as an extra first number.
        void TakeWidth(bool extra)
        {
            if (widthTaken) return;
            widthTaken = true;
            if (extra && stack.Count > 0) { width = _nominalWidth + stack[0]; stack.RemoveAt(0); }
        }

        bool Run(int start, int end, int depth)
        {
            int i = start;
            while (i < end)
            {
                int b = _d[i++];
                if (b >= 32 || b == 28)
                {
                    if (b == 28) { stack.Add((short)Be16(i)); i += 2; }
                    else if (b <= 246) stack.Add(b - 139);
                    else if (b <= 250) stack.Add((b - 247) * 256 + _d[i++] + 108);
                    else if (b <= 254) stack.Add(-(b - 251) * 256 - _d[i++] - 108);
                    else { int v = (_d[i] << 24) | (_d[i + 1] << 16) | (_d[i + 2] << 8) | _d[i + 3]; i += 4; stack.Add(v / 65536.0); }
                    continue;
                }
                var a = stack;
                int n = a.Count;
                switch (b)
                {
                    case 1: case 3: case 18: case 23: // stems
                        TakeWidth(n % 2 == 1); stems += stack.Count / 2; stack.Clear(); break;
                    case 19: case 20: // hintmask, cntrmask: stems given before the mask count too
                        TakeWidth(n % 2 == 1); stems += stack.Count / 2; stack.Clear(); i += (stems + 7) / 8; break;
                    case 21: TakeWidth(n > 2); n = a.Count; MoveTo(a[n - 2], a[n - 1]); a.Clear(); break;
                    case 22: TakeWidth(n > 1); n = a.Count; MoveTo(a[n - 1], 0); a.Clear(); break;
                    case 4: TakeWidth(n > 1); n = a.Count; MoveTo(0, a[n - 1]); a.Clear(); break;
                    case 5: for (int k = 0; k + 1 < n; k += 2) LineTo(a[k], a[k + 1]); a.Clear(); break;
                    case 6: case 7:
                    {
                        bool horizontal = b == 6;
                        for (int k = 0; k < n; k++) { if (horizontal) LineTo(a[k], 0); else LineTo(0, a[k]); horizontal = !horizontal; }
                        a.Clear(); break;
                    }
                    case 8: for (int k = 0; k + 5 < n; k += 6) CurveTo(a[k], a[k + 1], a[k + 2], a[k + 3], a[k + 4], a[k + 5]); a.Clear(); break;
                    case 24: // rcurveline
                    {
                        int k = 0;
                        for (; k + 6 <= n - 2; k += 6) CurveTo(a[k], a[k + 1], a[k + 2], a[k + 3], a[k + 4], a[k + 5]);
                        LineTo(a[k], a[k + 1]); a.Clear(); break;
                    }
                    case 25: // rlinecurve
                    {
                        int k = 0;
                        for (; k + 2 <= n - 6; k += 2) LineTo(a[k], a[k + 1]);
                        CurveTo(a[k], a[k + 1], a[k + 2], a[k + 3], a[k + 4], a[k + 5]); a.Clear(); break;
                    }
                    case 26: // vvcurveto
                    {
                        int k = 0; double dx1 = 0;
                        if (n % 4 == 1) dx1 = a[k++];
                        for (; k + 3 < n; k += 4) { CurveTo(dx1, a[k], a[k + 1], a[k + 2], 0, a[k + 3]); dx1 = 0; }
                        a.Clear(); break;
                    }
                    case 27: // hhcurveto
                    {
                        int k = 0; double dy1 = 0;
                        if (n % 4 == 1) dy1 = a[k++];
                        for (; k + 3 < n; k += 4) { CurveTo(a[k], dy1, a[k + 1], a[k + 2], a[k + 3], 0); dy1 = 0; }
                        a.Clear(); break;
                    }
                    case 30: case 31: // vhcurveto, hvcurveto
                    {
                        bool horizontal = b == 31;
                        int k = 0;
                        while (k + 4 <= n)
                        {
                            double last = n - k == 5 ? a[k + 4] : 0;
                            if (horizontal) CurveTo(a[k], 0, a[k + 1], a[k + 2], last, a[k + 3]);
                            else CurveTo(0, a[k], a[k + 1], a[k + 2], a[k + 3], last);
                            k += 4;
                            horizontal = !horizontal;
                        }
                        a.Clear(); break;
                    }
                    case 10: case 29: // callsubr, callgsubr
                    {
                        var list = b == 10 ? _localSubrs : _globalSubrs;
                        int bias = list.Count < 1240 ? 107 : list.Count < 33900 ? 1131 : 32768;
                        int index = (int)a[^1] + bias; a.RemoveAt(a.Count - 1);
                        if (depth < 12 && Run(list[index].Start, list[index].End, depth + 1)) return true;
                        break;
                    }
                    case 11: return false; // return
                    case 14: TakeWidth(n == 1 || n == 5); Close(); return true; // endchar
                    case 12:
                    {
                        int op = _d[i++];
                        switch (op)
                        {
                            case 34: CurveTo(a[0], 0, a[1], a[2], a[3], 0); CurveTo(a[4], 0, a[5], -a[2], a[6], 0); break; // hflex
                            case 35: CurveTo(a[0], a[1], a[2], a[3], a[4], a[5]); CurveTo(a[6], a[7], a[8], a[9], a[10], a[11]); break; // flex
                            case 36: CurveTo(a[0], a[1], a[2], a[3], a[4], 0); CurveTo(a[5], 0, a[6], a[7], a[8], -(a[1] + a[3] + a[7])); break; // hflex1
                            case 37: // flex1
                            {
                                double dx = a[0] + a[2] + a[4] + a[6] + a[8], dy = a[1] + a[3] + a[5] + a[7] + a[9];
                                CurveTo(a[0], a[1], a[2], a[3], a[4], a[5]);
                                if (Math.Abs(dx) > Math.Abs(dy)) CurveTo(a[6], a[7], a[8], a[9], a[10], -dy);
                                else CurveTo(a[6], a[7], a[8], a[9], -dx, a[10]);
                                break;
                            }
                        }
                        a.Clear(); break;
                    }
                    default: a.Clear(); break; // anything else (arithmetic, storage) is not used for symbols
                }
            }
            return false;
        }

        Run(_charStrings[glyph].Start, _charStrings[glyph].End, 0);
        Close();
        return (width, sb.ToString().Trim());
    }
}
